import java.util.*;

class Solution {
    public int countDividingDigits(int n) {
        int x = n, count = 0;
        while (x > 0) {
            int d = x % 10;                       // last digit
            if (d != 0 && n % d == 0) count++;    // divide the ORIGINAL n
            x /= 10;
        }
        return count;
    }
}

